mapper.select:
SELECT id, biz_name, category_large, category_medium, category_small, latitude, longitude, address, created_at, SQRT( POW((latitude - #{lat}) * 111320, 2) + POW((longitude - #{lng}) * 111320 * COS(RADIANS(#{lat})), 2) ) AS distance FROM commercial_area
category_large = #{category}
HAVING distance <= #{radius} ORDER BY distance ASC, id ASC
